+// API keys and roles. Keys live in the store as `apiKeys` ({ key, name,
+// role }). Roles are ordered: each may do everything the one before it may.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (text) => createHash("sha256").update(String(text)).digest();
+
+/** The API key record for `key`, or an `unauthorized` AppError when it is missing or unknown. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || key === "") throw new AppError("unauthorized");
+  const given = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), given)) found ??= k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** True when `method` only reads data. */
+export function isRead(method) {
+  return method === "GET";
+}
+
+/** The role a request needs: the route's own (`needs`), else viewer to read and manager to change. */
+export function requiredRole(method, needs) {
+  return needs ?? (isRead(method) ? "viewer" : "manager");
+}
+
+/** Throws a `forbidden` AppError unless the key's role reaches `role`. */
+export function authorize(apiKey, role) {
+  const has = ROLES.indexOf(apiKey.role);
+  const wanted = ROLES.indexOf(role);
+  if (has < 0 || wanted < 0 || has < wanted) throw new AppError("forbidden", { role });
+}
